  build_design_prompt [expression="DESIGN phase only. Task: {value}. The hard admission limit is enforced by Arbor. Do not edit files and do not create commits. Return ONLY one valid JSON object with exactly one string field: {\"design\":\"the exact design text\"}. Arbor computes the digest after admission.", output_key=prompt, source_key=task, transform=template, type=transform];
  build_design_rework_prompt [expression="DESIGN rework only. Task: {value}. Operator note: {ctx.approval_note}. The hard admission limit is enforced by Arbor. Do not edit files and do not create commits. Return ONLY one valid JSON object with exactly one string field: {\"design\":\"the exact corrected design text\"}. Arbor computes the digest after admission.", output_key=prompt, source_key=task, transform=template, type=transform];
