  build_operator_rework_prompt [expression="OPERATOR REWORK. You are implementing an Arbor code change inside worktree {ctx.worktree_path}. Exact reviewed task: {value}. Frozen canonical work packet JSON: {ctx.coding_plan_work_packet_json}. Operator note: {ctx.approval_note}. Address the operator feedback in the same worktree. For compatibility with archived graphs, respond with ONLY one valid JSON object and no prose or Markdown: {\"status\":\"implemented\",\"summary\":\"what changed\"} or {\"status\":\"declined\",\"summary\":\"why no change was made\"}. Arbor treats this object as advisory only and decides the outcome from the owned workspace.", output_key=prompt, source_key=task, transform=template, type=transform];
  build_protocol_format_repair_prompt [expression="FORMAT REPAIR ONLY. Do not edit files and do not re-implement the task. Your previous response was not valid protocol JSON. Respond with ONLY one valid JSON object and no prose or Markdown: {\"status\":\"implemented\",\"summary\":\"what changed\"} or {\"status\":\"declined\",\"summary\":\"why no change was made\"}. Optional summary must be a string. Arbor treats this object as advisory only and decides the outcome from the owned workspace.", output_key=prompt, transform=constant, type=transform];
  build_review_rework_prompt [expression="COUNCIL REVIEW REWORK. You are implementing an Arbor code change inside worktree {ctx.worktree_path}. Exact reviewed task: {value}. Frozen canonical work packet JSON: {ctx.coding_plan_work_packet_json}. Structured review feedback JSON: {ctx.review.feedback_json}. Address the council review feedback in the same worktree. For compatibility with archived graphs, respond with ONLY one valid JSON object and no prose or Markdown: {\"status\":\"implemented\",\"summary\":\"what changed\"} or {\"status\":\"declined\",\"summary\":\"why no change was made\"}. Arbor treats this object as advisory only and decides the outcome from the owned workspace.", output_key=prompt, source_key=task, transform=template, type=transform];
  build_validation_rework_prompt [expression="VALIDATION REWORK. You are implementing an Arbor code change inside worktree {ctx.worktree_path}. Exact reviewed task: {value}. Frozen canonical work packet JSON: {ctx.coding_plan_work_packet_json}. Structured validation feedback JSON (may be empty on operator approval rework): {ctx.validation.feedback_json}. Operator approval note (when present): {ctx.approval_note}. Approval request id (when present): {ctx.approval_request_id}. Fix the validation issues in the same worktree without fabricating missing validator evidence. For compatibility with archived graphs, respond with ONLY one valid JSON object and no prose or Markdown: {\"status\":\"implemented\",\"summary\":\"what changed\"} or {\"status\":\"declined\",\"summary\":\"why no change was made\"}. Arbor treats this object as advisory only and decides the outcome from the owned workspace.", output_key=prompt, source_key=task, transform=template, type=transform];
